import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import type { IncomingMessage, ServerResponse } from "node:http";
import type { Plugin, ViteDevServer } from "vite";

export const DEV_SERVER_MODE_EVENT = "vibe:dev-server-mode";
export const BOOT_PROGRESS_EVENT = "vibe:boot-progress";
export const UPDATE_PROGRESS_EVENT = "vibe:update-progress";
export const FULL_RELOAD_ENV_VAR = "VIBE_HMR_FULL_RELOAD";

export type BuildErrorData = {
  file: string | null;
  line: number | null;
  message: string;
};

export type BootProgressData = {
  buildError: BuildErrorData | null;
  clientIdleMs: number | null;
  clientModules: number;
  ssrIdleMs: number | null;
  ssrModules: number;
};

export type UpdateProgressData = {
  batch: number;
  buildError: BuildErrorData | null;
  clientModules: number;
  done: boolean;
  idleMs: number | null;
  ssrModules: number;
  trigger: "flush" | "restart" | "watch";
};

export interface HmrGateOptions {
  /** Use one full reload instead of granular watcher replay only. Defaults to VIBE_HMR_FULL_RELOAD. */
  fullReload?: boolean;
  /** Maximum hold in either mode after the first queued event. */
  failOpenMs?: number;
  /** Bundled dev drain window after a flush. */
  drainMs?: number;
  /** Maximum time a bundled patch request may remain parked. */
  maxHoldMs?: number;
  /** Bundled dev startup window where restart reloads pass through. */
  startupGraceMs?: number;
  /** Watcher events intercepted in classic mode. */
  events?: Array<"change" | "add" | "unlink">;
  /** File path substrings that bypass the classic gate. */
  passthrough?: string[];
}

type PendingEvents = Map<string, Set<"change" | "add" | "unlink">>;
type SendTarget = {
  send: (...args: unknown[]) => unknown;
  on?: (event: string, listener: (...args: unknown[]) => void) => void;
  off?: (event: string, listener: (...args: unknown[]) => void) => void;
  clients?: Iterable<SendTarget>;
};
type ParkedRequest = {
  cancel: () => void;
  generation: number;
  release: () => void;
};
type QueuedFrame = {
  args: unknown[];
  generation: number;
  original: SendTarget["send"];
  target: SendTarget;
};
type WrappedSend = {
  generation: number;
  original: SendTarget["send"];
};
type GenerationState = {
  drainUntil: number;
  failOpenTimer: NodeJS.Timeout | null;
  heldReload: boolean;
  reloadPassthroughUntil: number;
  replayTimer: NodeJS.Timeout | null;
  restartTimer: NodeJS.Timeout | null;
  server: ViteDevServer;
  startedAt: number;
  startupGraceUntil: number;
};
type TransformState = {
  ids: Set<string>;
  lastTransformAt: number;
};
type UpdateBatch = {
  id: number;
  idsByEnvironment: Map<string, Set<string>>;
  lastTransformAt: number;
  openedAt: number;
  trigger: UpdateProgressData["trigger"];
};
type ReloadNeededListener = (payload: unknown, client: unknown) => void;
type ReloadNeededBuffers = Map<ReloadNeededListener, Map<unknown, unknown>>;
type RestartExpectation = {
  sourceGeneration: number;
  timer: NodeJS.Timeout | null;
};

function requestPathname(request: IncomingMessage): string {
  const url = request.url ?? "";
  const queryIndex = url.indexOf("?");
  return queryIndex === -1 ? url : url.slice(0, queryIndex);
}

function sendJson(
  response: ServerResponse,
  status: number,
  body: Record<string, unknown>,
): void {
  response.writeHead(status, { "Content-Type": "application/json" });
  response.end(JSON.stringify(body));
}

/** Always-bypassed path substrings (merged with options.passthrough). */
const DEFAULT_PASSTHROUGH = ["tailwind.config.vibe.json"];
const BOOT_PROGRESS_MIN_INTERVAL_MS = 500;
const UPDATE_PROGRESS_MIN_INTERVAL_MS = 500;
const UPDATE_SETTLE_MS = 800;
const UPDATE_FLUSH_SETTLE_MS = 5_000;
const UPDATE_MIN_MODULES = 10;
const UPDATE_MIN_DURATION_MS = 1_500;

function firstBuildError(error: unknown): BuildErrorData | null {
  if (error === null || typeof error !== "object") return null;
  const candidate = error as {
    errors?: unknown;
    id?: unknown;
    loc?: { file?: unknown; line?: unknown };
    message?: unknown;
  };
  const first = Array.isArray(candidate.errors)
    ? (candidate.errors[0] as typeof candidate | undefined)
    : candidate;
  if (!first || typeof first !== "object") return null;
  const message =
    typeof first.message === "string" ? first.message : "Build failed";
  const file =
    typeof first.loc?.file === "string"
      ? first.loc.file
      : typeof first.id === "string"
        ? first.id
        : null;
  return {
    message,
    file,
    line: typeof first.loc?.line === "number" ? first.loc.line : null,
  };
}

export function hmrGatePlugin(options: HmrGateOptions = {}): Plugin {
  const gatedEvents = new Set(options.events ?? ["change", "add", "unlink"]);
  const passthrough = [...DEFAULT_PASSTHROUGH, ...(options.passthrough ?? [])];
  const pending: PendingEvents = new Map();
  const lastFlushedHashes = new Map<string, string>();
  const failOpenMs = options.failOpenMs ?? 240_000;
  const fullReload =
    options.fullReload ?? process.env[FULL_RELOAD_ENV_VAR] !== "false";
  let spawnGeneration: number | null = null;
  let currentGeneration = 0;
  const generationStates = new Map<number, GenerationState>();
  let restartExpectation: RestartExpectation | null = null;
  const cleanedGenerations = new Set<number>();
  const generationByEnvironment = new WeakMap<object, number>();
  const httpCloseServers = new Map<
    number,
    {
      listener: () => void;
      server: NonNullable<ViteDevServer["httpServer"]>;
    }
  >();
  const originalWatchers = new Map<
    number,
    {
      emit: ViteDevServer["watcher"]["emit"];
      server: ViteDevServer;
    }
  >();
  let transportMode = false;
  let base = "/";
  const drainMs = options.drainMs ?? 1_500;
  const maxHoldMs = options.maxHoldMs ?? 240_000;
  const parked: ParkedRequest[] = [];
  const queuedFrames: QueuedFrame[] = [];
  const wrappedSends = new Map<SendTarget, WrappedSend>();
  const connectionListeners: Array<{
    generation: number;
    listener: (...args: unknown[]) => void;
    target: SendTarget;
  }> = [];
  const socketConnectionListeners: Array<{
    generation: number;
    listener: (...args: unknown[]) => void;
    target: SendTarget;
  }> = [];
  const wrappedHotOn = new Map<
    SendTarget,
    { generation: number; original: NonNullable<SendTarget["on"]> }
  >();
  const transformsByEnvironment = new Map<string, TransformState>();
  const buildErrorsByEnvironment = new Map<string, BuildErrorData>();
  const bufferedReloadNeeded = new Map<number, ReloadNeededBuffers>();
  const pendingReloadReplay = new Map<number, ReloadNeededBuffers>();
  const reloadNeededListeners = new Map<number, Set<ReloadNeededListener>>();
  let bootProgressSentAt = 0;
  let bootProgressTimer: NodeJS.Timeout | null = null;
  let lastBootProgressKey = "";
  let updateBatch: UpdateBatch | null = null;
  let updateBatchSequence = 0;
  let updateProgressSentAt = 0;
  let lastUpdateProgressKey = "";
  let updateProgressTimer: NodeJS.Timeout | null = null;
  let updateSettleTimer: NodeJS.Timeout | null = null;

  function isPassthrough(file: unknown): boolean {
    if (typeof file !== "string") return true;
    if (file.includes("node_modules/.vite")) return true;
    return passthrough.some((substring) => file.includes(substring));
  }

  function environmentName(
    context: { environment?: { name?: string } } | undefined,
    ssr = false,
  ): string {
    return context?.environment?.name ?? (ssr ? "ssr" : "client");
  }

  function currentBuildError(): BuildErrorData | null {
    return buildErrorsByEnvironment.values().next().value ?? null;
  }

  function buildErrorKey(error: BuildErrorData | null): string {
    return error
      ? `${error.message}:${error.file ?? ""}:${error.line ?? ""}`
      : "";
  }

  function bootProgressData(): BootProgressData {
    const now = Date.now();
    const idle = (name: string): number | null => {
      const transformedAt = transformsByEnvironment.get(name)?.lastTransformAt;
      return transformedAt === undefined ? null : now - transformedAt;
    };
    return {
      ssrModules: transformsByEnvironment.get("ssr")?.ids.size ?? 0,
      clientModules: transformsByEnvironment.get("client")?.ids.size ?? 0,
      ssrIdleMs: idle("ssr"),
      clientIdleMs: idle("client"),
      buildError: currentBuildError(),
    };
  }

  function sendCustomEvent(
    event: string,
    data: BootProgressData | UpdateProgressData | Record<string, unknown>,
  ): void {
    generationStates
      .get(currentGeneration)
      ?.server.ws.send({ type: "custom", event, data });
  }

  function broadcastBootProgress(): void {
    const data = bootProgressData();
    const key = `${data.ssrModules}:${data.clientModules}:${buildErrorKey(data.buildError)}`;
    if (
      key === lastBootProgressKey ||
      !generationStates.has(currentGeneration)
    ) {
      return;
    }
    lastBootProgressKey = key;
    bootProgressSentAt = Date.now();
    sendCustomEvent(BOOT_PROGRESS_EVENT, data);
  }

  function scheduleBootProgress(): void {
    if (bootProgressTimer !== null) return;
    const wait =
      bootProgressSentAt + BOOT_PROGRESS_MIN_INTERVAL_MS - Date.now();
    if (wait <= 0) {
      broadcastBootProgress();
      return;
    }
    bootProgressTimer = setTimeout(() => {
      bootProgressTimer = null;
      broadcastBootProgress();
    }, wait);
    bootProgressTimer.unref?.();
  }

  function updateBatchModuleCount(batch: UpdateBatch): number {
    return (
      (batch.idsByEnvironment.get("ssr")?.size ?? 0) +
      (batch.idsByEnvironment.get("client")?.size ?? 0)
    );
  }

  function updateBatchEarned(batch: UpdateBatch): boolean {
    const total = updateBatchModuleCount(batch);
    return (
      total >= UPDATE_MIN_MODULES ||
      (total > 0 && Date.now() - batch.openedAt >= UPDATE_MIN_DURATION_MS)
    );
  }

  function broadcastUpdateProgress(
    overrides: Partial<Pick<UpdateProgressData, "done" | "trigger">> = {},
  ): void {
    const batch = updateBatch;
    if (!batch || !generationStates.has(currentGeneration)) return;
    const trigger = overrides.trigger ?? batch.trigger;
    if (trigger !== "restart" && !updateBatchEarned(batch)) return;
    const now = Date.now();
    const data: UpdateProgressData = {
      batch: batch.id,
      trigger,
      ssrModules: batch.idsByEnvironment.get("ssr")?.size ?? 0,
      clientModules: batch.idsByEnvironment.get("client")?.size ?? 0,
      idleMs: batch.lastTransformAt === 0 ? null : now - batch.lastTransformAt,
      done: overrides.done ?? false,
      buildError: currentBuildError(),
    };
    const key = `${data.batch}:${data.trigger}:${data.ssrModules}:${data.clientModules}:${data.done}:${buildErrorKey(data.buildError)}`;
    if (key === lastUpdateProgressKey) return;
    lastUpdateProgressKey = key;
    updateProgressSentAt = now;
    sendCustomEvent(UPDATE_PROGRESS_EVENT, data);
  }

  function scheduleUpdateProgress(): void {
    if (updateProgressTimer !== null) return;
    const wait =
      updateProgressSentAt + UPDATE_PROGRESS_MIN_INTERVAL_MS - Date.now();
    if (wait <= 0) {
      broadcastUpdateProgress();
      return;
    }
    updateProgressTimer = setTimeout(() => {
      updateProgressTimer = null;
      broadcastUpdateProgress();
    }, wait);
    updateProgressTimer.unref?.();
  }

  function clearUpdateTimers(): void {
    if (updateProgressTimer !== null) clearTimeout(updateProgressTimer);
    if (updateSettleTimer !== null) clearTimeout(updateSettleTimer);
    updateProgressTimer = null;
    updateSettleTimer = null;
  }

  function armUpdateSettle(delay: number): void {
    if (updateSettleTimer !== null) clearTimeout(updateSettleTimer);
    updateSettleTimer = setTimeout(() => {
      updateSettleTimer = null;
      if (!updateBatch) return;
      if (updateProgressTimer !== null) clearTimeout(updateProgressTimer);
      updateProgressTimer = null;
      broadcastUpdateProgress({ done: true });
      updateBatch = null;
    }, delay);
    updateSettleTimer.unref?.();
  }

  function openWatchBatchIfNone(): void {
    if (updateBatch) return;
    updateBatch = {
      id: ++updateBatchSequence,
      trigger: "watch",
      openedAt: Date.now(),
      idsByEnvironment: new Map(),
      lastTransformAt: 0,
    };
    armUpdateSettle(UPDATE_SETTLE_MS);
  }

  function noteUpdateFlush(): void {
    // A watcher batch that already observed transforms belongs to the preceding
    // change. Finish it before opening a distinct batch for this explicit flush.
    if (updateBatch?.trigger === "watch" && updateBatch.lastTransformAt !== 0) {
      clearUpdateTimers();
      broadcastUpdateProgress({ done: true });
      updateBatch = null;
    }
    if (!updateBatch) {
      updateBatch = {
        id: ++updateBatchSequence,
        trigger: "flush",
        openedAt: Date.now(),
        idsByEnvironment: new Map(),
        lastTransformAt: 0,
      };
    } else {
      updateBatch.trigger = "flush";
      if (updateBatch.lastTransformAt === 0) updateBatch.openedAt = Date.now();
    }
    scheduleUpdateProgress();
    armUpdateSettle(
      updateBatch.lastTransformAt === 0
        ? UPDATE_FLUSH_SETTLE_MS
        : UPDATE_SETTLE_MS,
    );
  }

  function noteUpdateRestart(): void {
    if (!updateBatch) noteUpdateFlush();
    clearUpdateTimers();
    broadcastUpdateProgress({ trigger: "restart", done: true });
    updateBatch = null;
  }

  function resetProgress(): void {
    if (bootProgressTimer !== null) clearTimeout(bootProgressTimer);
    bootProgressTimer = null;
    transformsByEnvironment.clear();
    buildErrorsByEnvironment.clear();
    bootProgressSentAt = 0;
    lastBootProgressKey = "";
    clearUpdateTimers();
    updateBatch = null;
    updateProgressSentAt = 0;
    lastUpdateProgressKey = "";
  }

  function isPatchRequest(url: string): boolean {
    const escapedBase = base.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    return new RegExp(`^${escapedBase}hmr_patch_\\d+\\.js(?:\\?|$)`).test(url);
  }

  function fileContentHash(file: string): string | null {
    try {
      return createHash("sha1").update(readFileSync(file)).digest("hex");
    } catch {
      return null;
    }
  }

  function clearFailOpenTimer(generation = currentGeneration): void {
    const state = generationStates.get(generation);
    if (state?.failOpenTimer) {
      clearTimeout(state.failOpenTimer);
      state.failOpenTimer = null;
    }
  }

  function armFailOpenTimer(generation = currentGeneration): void {
    const state = generationStates.get(generation);
    if (!state || state.failOpenTimer !== null) return;
    const timer = setTimeout(() => {
      if (state.failOpenTimer !== timer) return;
      state.failOpenTimer = null;
      if (transportMode) {
        flushTransport(generation);
      } else {
        flushClassic(generation);
      }
    }, failOpenMs);
    state.failOpenTimer = timer;
    timer.unref?.();
  }

  function initialBuildPending(generation: number): boolean {
    const client = generationStates.get(generation)?.server.environments
      ?.client as
      | { bundledDev?: { initialBuildCompleted?: boolean } }
      | undefined;
    const bundledDev = client?.bundledDev;
    return (
      bundledDev !== undefined && bundledDev.initialBuildCompleted !== true
    );
  }

  function gateSendTarget(
    target: SendTarget,
    generation = currentGeneration,
  ): void {
    if (wrappedSends.has(target)) return;
    const original = target.send;
    wrappedSends.set(target, { generation, original });
    target.send = (...args: unknown[]) => {
      const state = generationStates.get(generation);
      if (!state) return original.apply(target, args);
      const payload = args[0] as
        | { ifFallback?: boolean; type?: string }
        | undefined;
      if (
        payload?.type === "update" ||
        payload?.type === "bundled-dev-update"
      ) {
        queuedFrames.push({ args, generation, original, target });
        openWatchBatchIfNone();
        armFailOpenTimer(generation);
        return;
      }
      if (payload?.type === "full-reload") {
        if (
          payload.ifFallback === true ||
          Date.now() < state.reloadPassthroughUntil ||
          Date.now() < state.startupGraceUntil ||
          initialBuildPending(generation)
        ) {
          markRestartFreshnessObserved(generation);
          return original.apply(target, args);
        }
        state.heldReload = true;
        openWatchBatchIfNone();
        armFailOpenTimer(generation);
        return;
      }
      return original.apply(target, args);
    };
  }

  function gateConnectionSource(
    target: SendTarget,
    generation: number,
    announceConnections: boolean,
  ): void {
    if (typeof target.on !== "function") return;
    const listener = (_data: unknown, client: unknown) => {
      if (
        client &&
        typeof client === "object" &&
        typeof (client as SendTarget).send === "function"
      ) {
        const sendTarget = client as SendTarget;
        gateSendTarget(sendTarget, generation);
        const rawSocket = (client as { socket?: unknown }).socket;
        if (
          !announceConnections &&
          rawSocket !== null &&
          typeof rawSocket === "object"
        ) {
          return;
        }
        sendTarget.send({
          type: "custom",
          event: DEV_SERVER_MODE_EVENT,
          data: {
            mode: transportMode ? "bundled" : "classic",
            ...(spawnGeneration === null
              ? {}
              : { generation: spawnGeneration }),
          },
        });
        sendTarget.send({
          type: "custom",
          event: BOOT_PROGRESS_EVENT,
          data: bootProgressData(),
        });
      }
    };
    target.on("vite:client:connect", listener);
    connectionListeners.push({ generation, listener, target });
  }

  function gateSocketConnections(
    target: SendTarget,
    generation: number,
  ): boolean {
    if (typeof target.on !== "function") return false;
    const listener = (socket: unknown) => {
      if (
        !socket ||
        typeof socket !== "object" ||
        typeof (socket as SendTarget).send !== "function"
      ) {
        return;
      }
      const send = (socket as SendTarget).send.bind(socket);
      try {
        send(
          JSON.stringify({
            type: "custom",
            event: DEV_SERVER_MODE_EVENT,
            data: {
              mode: transportMode ? "bundled" : "classic",
              ...(spawnGeneration === null
                ? {}
                : { generation: spawnGeneration }),
            },
          }),
        );
        send(
          JSON.stringify({
            type: "custom",
            event: BOOT_PROGRESS_EVENT,
            data: bootProgressData(),
          }),
        );
      } catch {
        // A disconnected client should not affect the dev server.
      }
    };
    target.on("connection", listener);
    socketConnectionListeners.push({ generation, listener, target });
    return true;
  }

  function gateReloadNeeded(target: SendTarget, generation: number): void {
    if (typeof target.on !== "function" || wrappedHotOn.has(target)) return;
    const original = target.on.bind(target);
    target.on = ((event: string, listener: ReloadNeededListener) => {
      if (event !== "vite:bundled-dev:reload-needed") {
        return original(event, listener);
      }
      const listeners = reloadNeededListeners.get(generation) ?? new Set();
      listeners.add(listener);
      reloadNeededListeners.set(generation, listeners);
      return original(event, (payload: unknown, client: unknown) => {
        const state = generationStates.get(generation);
        if (
          !state ||
          Date.now() < state.startupGraceUntil ||
          initialBuildPending(generation)
        ) {
          listener(payload, client);
          return;
        }
        const allBuffered =
          bufferedReloadNeeded.get(generation) ??
          new Map<ReloadNeededListener, Map<unknown, unknown>>();
        const buffered = allBuffered.get(listener) ?? new Map();
        buffered.set(client, payload);
        allBuffered.set(listener, buffered);
        bufferedReloadNeeded.set(generation, allBuffered);
        openWatchBatchIfNone();
        armFailOpenTimer(generation);
      });
    }) as SendTarget["on"];
    wrappedHotOn.set(target, { generation, original });
  }

  function gateTransportTargets(
    viteServer: ViteDevServer,
    generation: number,
    announceConnections: boolean,
  ): void {
    const targets = new Set<SendTarget>();
    targets.add(viteServer.ws as unknown as SendTarget);
    targets.add(viteServer.hot as unknown as SendTarget);
    for (const environment of Object.values(viteServer.environments ?? {})) {
      targets.add(environment.hot as unknown as SendTarget);
    }

    for (const target of targets) {
      if (!target || typeof target.send !== "function") continue;
      gateSendTarget(target, generation);
      gateConnectionSource(target, generation, announceConnections);
      for (const client of target.clients ?? []) {
        gateSendTarget(client, generation);
      }
    }

    const bundledClients = (
      viteServer.environments?.client?.bundledDev as
        | { clients?: { getAll?: () => SendTarget[] } }
        | undefined
    )?.clients?.getAll?.();
    for (const client of bundledClients ?? []) {
      gateSendTarget(client, generation);
    }

    const hot = viteServer.environments?.client?.hot as SendTarget | undefined;
    if (hot) gateReloadNeeded(hot, generation);
  }

  function releaseParked(
    cancel = false,
    generation = currentGeneration,
  ): number {
    const entries = parked.filter((entry) => entry.generation === generation);
    for (const entry of entries) {
      if (cancel) entry.cancel();
      else entry.release();
    }
    return entries.length;
  }

  function transportPendingCount(generation = currentGeneration): number {
    const state = generationStates.get(generation);
    const hasBufferedReload = hasReloadNeededEntries(
      bufferedReloadNeeded.get(generation),
    );
    const hasPendingReplay = hasReloadNeededEntries(
      pendingReloadReplay.get(generation),
    );
    return (
      parked.filter((entry) => entry.generation === generation).length +
      queuedFrames.filter((entry) => entry.generation === generation).length +
      (state?.heldReload || hasBufferedReload || hasPendingReplay ? 1 : 0)
    );
  }

  function hasReloadNeededEntries(
    entries: ReloadNeededBuffers | undefined,
  ): boolean {
    return [...(entries?.values() ?? [])].some((clients) => clients.size > 0);
  }

  function sendRawFullReload(generation: number): void {
    const first = [...wrappedSends].find(
      ([, wrapped]) => wrapped.generation === generation,
    );
    if (first) first[1].original.call(first[0], { type: "full-reload" });
  }

  function clearRestartExpectation(): void {
    if (!restartExpectation) return;
    if (restartExpectation.timer !== null) {
      clearTimeout(restartExpectation.timer);
    }
    restartExpectation = null;
  }

  function markRestartFreshnessObserved(generation: number): void {
    if (
      !restartExpectation ||
      generation !== currentGeneration ||
      generation < restartExpectation.sourceGeneration
    ) {
      return;
    }
    clearRestartExpectation();
  }

  function sendRestartFallback(expectation: RestartExpectation): void {
    if (restartExpectation !== expectation) return;
    restartExpectation = null;
    sendRawFullReload(currentGeneration);
  }

  function scheduleRestartFallback(
    expectation: RestartExpectation,
    delay: number,
  ): void {
    if (restartExpectation !== expectation) return;
    if (expectation.timer !== null) clearTimeout(expectation.timer);
    expectation.timer = setTimeout(
      () => sendRestartFallback(expectation),
      delay,
    );
    expectation.timer.unref?.();
  }

  function expectRestartFreshness(
    sourceGeneration: number,
  ): RestartExpectation {
    clearRestartExpectation();
    const expectation: RestartExpectation = {
      sourceGeneration,
      timer: null,
    };
    restartExpectation = expectation;
    scheduleRestartFallback(expectation, maxHoldMs);
    return expectation;
  }

  function scheduleRestart(
    generation: number,
    released: number,
    previousDrainUntil: number,
  ): void {
    const state = generationStates.get(generation);
    if (!state) return;
    const restart = state.server.restart;
    if (typeof restart !== "function") {
      sendRawFullReload(generation);
      return;
    }

    const delay = Math.max(
      released > 0 ? drainMs : 0,
      previousDrainUntil - Date.now(),
      0,
    );
    if (state.restartTimer !== null) clearTimeout(state.restartTimer);
    const timer = setTimeout(() => {
      if (state.restartTimer !== timer) return;
      state.restartTimer = null;
      if (!generationStates.has(generation)) return;
      const expectation = expectRestartFreshness(generation);
      Promise.resolve()
        .then(() => restart.call(state.server))
        .catch(() => undefined)
        .finally(() => {
          scheduleRestartFallback(expectation, Math.max(drainMs, 1));
        });
    }, delay);
    state.restartTimer = timer;
    timer.unref?.();
  }

  function scheduleReloadNeededReplay(
    generation: number,
    released: number,
    previousDrainUntil: number,
  ): boolean {
    const state = generationStates.get(generation);
    const buffered = bufferedReloadNeeded.get(generation);
    if (!state || !buffered || buffered.size === 0) return false;

    const pending =
      pendingReloadReplay.get(generation) ??
      new Map<ReloadNeededListener, Map<unknown, unknown>>();
    for (const [listener, entries] of buffered) {
      const pendingEntries = pending.get(listener) ?? new Map();
      for (const [client, payload] of entries) {
        pendingEntries.set(client, payload);
      }
      pending.set(listener, pendingEntries);
    }
    buffered.clear();
    pendingReloadReplay.set(generation, pending);
    const delay = Math.max(
      released > 0 ? drainMs : 0,
      previousDrainUntil - Date.now(),
      0,
    );
    if (state.replayTimer !== null) clearTimeout(state.replayTimer);
    const timer = setTimeout(() => {
      if (state.replayTimer !== timer) return;
      state.replayTimer = null;
      // The bundled-dev listener sends its own full-reload message. Let that
      // message escape the gate while this replay is being delivered.
      state.reloadPassthroughUntil = Date.now() + Math.max(drainMs, 1);
      const entries = [...(pendingReloadReplay.get(generation) ?? new Map())];
      pendingReloadReplay.delete(generation);
      for (const [listener, clients] of entries) {
        for (const [client, payload] of clients) listener(payload, client);
      }
    }, delay);
    state.replayTimer = timer;
    timer.unref?.();
    return true;
  }

  function flushTransport(generation = currentGeneration): {
    released: number;
    reload: boolean;
    updates: number;
  } {
    const state = generationStates.get(generation);
    if (!state) return { released: 0, reload: false, updates: 0 };
    clearFailOpenTimer(generation);
    const hadWork = transportPendingCount(generation) > 0;
    const previousDrainUntil = state.drainUntil;
    const released = releaseParked(false, generation);
    if (hadWork) state.drainUntil = Date.now() + drainMs;
    const frames = queuedFrames.filter(
      (frame) => frame.generation === generation,
    );
    for (const frame of frames) {
      const index = queuedFrames.indexOf(frame);
      if (index !== -1) queuedFrames.splice(index, 1);
    }
    for (const frame of frames) {
      frame.original.apply(frame.target, frame.args);
    }
    const updates = frames.length;
    const heldReload = state.heldReload;
    const reload =
      heldReload ||
      [...(bufferedReloadNeeded.get(generation)?.values() ?? [])].some(
        (entries) => entries.size > 0,
      );
    state.heldReload = false;
    if (hadWork) noteUpdateFlush();
    if (
      reload &&
      (heldReload ||
        !scheduleReloadNeededReplay(generation, released, previousDrainUntil))
    ) {
      bufferedReloadNeeded.get(generation)?.clear();
      pendingReloadReplay.get(generation)?.clear();
      noteUpdateRestart();
      scheduleRestart(generation, released, previousDrainUntil);
    }
    return { released, reload, updates };
  }

  function flushClassic(generation = currentGeneration): string[] {
    clearFailOpenTimer(generation);
    const state = generationStates.get(generation);
    const originalWatcher = originalWatchers.get(generation);
    if (!state || !originalWatcher) return [];

    const entries = [...pending.entries()];
    pending.clear();
    if (entries.length > 0) noteUpdateFlush();
    for (const [file] of entries) {
      state.server.moduleGraph.onFileChange(file);
    }
    for (const [file, events] of entries) {
      for (const event of events) {
        originalWatcher.emit(event, file);
      }
      const hash = fileContentHash(file);
      if (hash === null) {
        lastFlushedHashes.delete(file);
      } else {
        lastFlushedHashes.set(file, hash);
      }
    }
    if (entries.length > 0 && fullReload) {
      state.server.ws.send({ type: "full-reload" });
    }
    return entries.map(([file]) => file);
  }

  function cleanupGeneration(generation: number): void {
    if (cleanedGenerations.has(generation)) return;
    cleanedGenerations.add(generation);

    const httpClose = httpCloseServers.get(generation);
    if (httpClose) {
      httpClose.server.off("close", httpClose.listener);
      httpCloseServers.delete(generation);
    }
    const originalWatcher = originalWatchers.get(generation);
    if (originalWatcher) {
      originalWatcher.server.watcher.emit = originalWatcher.emit;
      originalWatchers.delete(generation);
    }
    for (let index = connectionListeners.length - 1; index >= 0; index -= 1) {
      const connection = connectionListeners[index];
      if (connection.generation !== generation) continue;
      connection.target.off?.("vite:client:connect", connection.listener);
      connectionListeners.splice(index, 1);
    }
    for (
      let index = socketConnectionListeners.length - 1;
      index >= 0;
      index -= 1
    ) {
      const connection = socketConnectionListeners[index];
      if (connection.generation !== generation) continue;
      connection.target.off?.("connection", connection.listener);
      socketConnectionListeners.splice(index, 1);
    }
    for (const [target, wrapped] of wrappedHotOn) {
      if (wrapped.generation !== generation) continue;
      target.on = wrapped.original;
      wrappedHotOn.delete(target);
    }
    for (const [target, wrapped] of wrappedSends) {
      if (wrapped.generation !== generation) continue;
      target.send = wrapped.original;
      wrappedSends.delete(target);
    }
    for (let index = queuedFrames.length - 1; index >= 0; index -= 1) {
      if (queuedFrames[index].generation === generation) {
        queuedFrames.splice(index, 1);
      }
    }
    releaseParked(true, generation);
    bufferedReloadNeeded.delete(generation);
    pendingReloadReplay.delete(generation);
    reloadNeededListeners.delete(generation);

    const state = generationStates.get(generation);
    if (state) {
      if (state.failOpenTimer !== null) clearTimeout(state.failOpenTimer);
      if (state.replayTimer !== null) clearTimeout(state.replayTimer);
      if (state.restartTimer !== null) clearTimeout(state.restartTimer);
      generationStates.delete(generation);
    }

    if (generation !== currentGeneration) return;
    pending.clear();
    lastFlushedHashes.clear();
    resetProgress();
  }

  function contextGeneration(context: unknown): number | undefined {
    const environment = (context as { environment?: unknown } | undefined)
      ?.environment;
    // Vite 8 hands teardown hooks a plugin context with an `environment`; Vite 5
    // does not. Return undefined for an unknown environment so callers fall back
    // to the *oldest* still-live generation rather than clobbering the live one:
    // during a restart the successor already bumped `currentGeneration`, so
    // targeting it would tear down the live gate (see closeBundle/closeWatcher).
    return environment && typeof environment === "object"
      ? generationByEnvironment.get(environment)
      : undefined;
  }

  function oldestGeneration(): number | undefined {
    let oldest: number | undefined;
    for (const generation of generationStates.keys()) {
      if (oldest === undefined || generation < oldest) oldest = generation;
    }
    return oldest;
  }

  function teardownGeneration(context: unknown): number | undefined {
    return contextGeneration(context) ?? oldestGeneration();
  }

  return {
    name: "hmr-gate",
    apply: "serve",
    configResolved(config) {
      transportMode = config.experimental?.bundledDev === true;
      base = config.base;
      const rawGeneration = process.env.VIBE_SPAWN_GENERATION;
      const parsed =
        rawGeneration === undefined || rawGeneration === ""
          ? null
          : Number(rawGeneration);
      spawnGeneration =
        parsed !== null && Number.isSafeInteger(parsed) ? parsed : null;
    },
    transform(_code, id, transformOptions) {
      const name = environmentName(
        this as { environment?: { name?: string } },
        transformOptions?.ssr === true,
      );
      const progress = transformsByEnvironment.get(name) ?? {
        ids: new Set<string>(),
        lastTransformAt: 0,
      };
      progress.ids.add(id);
      progress.lastTransformAt = Date.now();
      transformsByEnvironment.set(name, progress);
      scheduleBootProgress();
      if (updateBatch) {
        const ids = updateBatch.idsByEnvironment.get(name) ?? new Set<string>();
        ids.add(id);
        updateBatch.idsByEnvironment.set(name, ids);
        updateBatch.lastTransformAt = Date.now();
        scheduleUpdateProgress();
        armUpdateSettle(UPDATE_SETTLE_MS);
      }
      return null;
    },
    buildStart() {
      const name = environmentName(this as { environment?: { name?: string } });
      transformsByEnvironment.delete(name);
      buildErrorsByEnvironment.delete(name);
      scheduleBootProgress();
    },
    buildEnd(error) {
      const name = environmentName(this as { environment?: { name?: string } });
      const parsed = firstBuildError(error);
      if (parsed) buildErrorsByEnvironment.set(name, parsed);
      else buildErrorsByEnvironment.delete(name);
      scheduleBootProgress();
    },
    configureServer(viteServer) {
      resetProgress();
      const generation = currentGeneration + 1;
      currentGeneration = generation;
      const startedAt = Date.now();
      const state: GenerationState = {
        drainUntil: 0,
        failOpenTimer: null,
        heldReload: false,
        reloadPassthroughUntil: 0,
        replayTimer: null,
        restartTimer: null,
        server: viteServer,
        startedAt,
        startupGraceUntil: startedAt + (options.startupGraceMs ?? 5_000),
      };
      generationStates.set(generation, state);
      const announcesSocketConnections = gateSocketConnections(
        viteServer.ws as unknown as SendTarget,
        generation,
      );
      for (const environment of Object.values(viteServer.environments ?? {})) {
        generationByEnvironment.set(environment, generation);
      }
      if (viteServer.httpServer) {
        const listener = () => cleanupGeneration(generation);
        httpCloseServers.set(generation, {
          listener,
          server: viteServer.httpServer,
        });
        viteServer.httpServer.once("close", listener);
      }
      if (transportMode) {
        gateTransportTargets(
          viteServer,
          generation,
          !announcesSocketConnections,
        );

        viteServer.middlewares.use((request, response, next) => {
          if (
            request.method !== "GET" ||
            !isPatchRequest(request.url ?? "") ||
            Date.now() < state.drainUntil
          ) {
            return next();
          }

          let released = false;
          let entry: ParkedRequest;
          const finish = (cancel: boolean) => {
            if (released) return;
            released = true;
            clearTimeout(timer);
            const index = parked.indexOf(entry);
            if (index !== -1) parked.splice(index, 1);
            if (transportPendingCount(generation) === 0) {
              clearFailOpenTimer(generation);
            }
            if (cancel) {
              sendJson(response, 503, { error: "gate_closed" });
            } else {
              next();
            }
          };
          const release = () => finish(false);
          const cancel = () => finish(true);
          const timer = setTimeout(release, maxHoldMs);
          timer.unref?.();
          entry = { cancel, generation, release };
          parked.push(entry);
          armFailOpenTimer(generation);
        });

        viteServer.middlewares.use((request, response, next) => {
          const pathname = requestPathname(request);
          const isStatus =
            request.method === "GET" && pathname === "/__hmr_gate";
          const isFlush =
            request.method === "POST" && pathname === "/__hmr_flush";
          if (!isStatus && !isFlush) return next();

          if (isFlush) {
            const { released, reload, updates } = flushTransport(generation);
            sendJson(response, 200, {
              flushed: [],
              count: released + updates + (reload ? 1 : 0),
              released,
              reload,
              mode: "transport-patch-hold",
            });
            return;
          }

          sendJson(response, 200, {
            enabled: true,
            pending: {},
            count: transportPendingCount(generation),
            heldReload:
              state.heldReload ||
              hasReloadNeededEntries(bufferedReloadNeeded.get(generation)) ||
              hasReloadNeededEntries(pendingReloadReplay.get(generation)),
            restartsOnReload:
              state.heldReload || !reloadNeededListeners.has(generation),
            startedAt: state.startedAt,
            mode: "transport-patch-hold",
          });
        });
        return;
      }

      const emit = viteServer.watcher.emit.bind(viteServer.watcher);
      originalWatchers.set(generation, {
        emit,
        server: viteServer,
      });
      viteServer.watcher.emit = ((
        event: string,
        ...args: unknown[]
      ): boolean => {
        if (event === "unlink" && typeof args[0] === "string") {
          lastFlushedHashes.delete(args[0]);
        }
        if (
          gatedEvents.has(event as "change" | "add" | "unlink") &&
          !isPassthrough(args[0])
        ) {
          const file = args[0] as string;
          if (event === "change") {
            const hash = fileContentHash(file);
            if (hash !== null && hash === lastFlushedHashes.get(file)) {
              pending.delete(file);
              if (pending.size === 0) clearFailOpenTimer(generation);
              return false;
            }
          }
          const events = pending.get(file) ?? new Set();
          events.add(event as "change" | "add" | "unlink");
          pending.set(file, events);
          openWatchBatchIfNone();
          armFailOpenTimer(generation);
          return false;
        }
        return emit(event, ...args);
      }) as ViteDevServer["watcher"]["emit"];

      viteServer.middlewares.use((request, response, next) => {
        const pathname = requestPathname(request);
        const isStatus = request.method === "GET" && pathname === "/__hmr_gate";
        const isFlush =
          request.method === "POST" && pathname === "/__hmr_flush";
        if (!isStatus && !isFlush) return next();

        if (isFlush) {
          const flushed = flushClassic(generation);
          sendJson(response, 200, {
            flushed,
            count: flushed.length,
            mode: fullReload ? "full-reload" : "granular",
          });
          return;
        }

        const serialized: Record<string, string[]> = {};
        for (const [file, events] of pending) {
          serialized[file] = [...events];
        }
        sendJson(response, 200, {
          enabled: true,
          pending: serialized,
          count: pending.size,
          mode: fullReload ? "full-reload" : "granular",
        });
      });

      // `pending` survives a restart (cleanupGeneration keeps it so a carried-over
      // edit isn't lost), but its fail-open deadline lived on the retired
      // generation's state. Re-arm it here so an edit inherited across a restart
      // still hits the ceiling instead of hanging until an explicit flush.
      if (pending.size > 0) armFailOpenTimer(generation);
    },
    closeBundle() {
      const generation = teardownGeneration(this);
      if (generation !== undefined) cleanupGeneration(generation);
    },
    closeWatcher() {
      const generation = teardownGeneration(this);
      if (generation !== undefined) cleanupGeneration(generation);
      // A restart expectation can only be observed by the live generation. Once
      // that generation's state is gone (final shutdown, in any teardown order),
      // the expectation is unclaimable — drop its dangling fallback timer. During
      // a restart the successor is still live, so this leaves it armed for it.
      if (!generationStates.has(currentGeneration)) clearRestartExpectation();
    },
  };
}
